-- GENERATED by `wfj generate` from data/gossip/gossip-d7.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["d70f9095da601e8e"] = { "Non so molto di magia, ma c'è un mago di nome Zaldimar che alloggia alla Locanda del Fiero Leone e che probabilmente potrebbe aiutarti.", "." },
  ["d71359686bc29c9f"] = { "Proteggimi da {name}! Devo tornare dalla mia nidiata.", "." },
  ["d71a25e7562df8ed"] = { "Mi sei mancato anche tu, tesoro. E finalmente sono a casa...", "." },
  ["d71f8e3c09c5a453"] = { "Coprimi, soldato! Devo tornare alla nostra base e preparare la flotta per un assalto aereo!", "." },
  ["d7261bf8d671d45f"] = { "Coprimi, provo a scappare!", "." },
  ["d7285469603a4787"] = { "Finché stai qui con noi, tu sei <il/la> <re/regina>. Se te ne vai, un altro ogre prende il tuo posto. Questa è la legge dei Gordok!", "." },
  ["d7288f82369a2a84"] = { "Ecco fatto. Tutto finito!", "." },
  ["d72c4124fc98ec55"] = { "Ho perso il mio ⟦Shroud of Unspoken Names=Manto dei Nomi Innominati⟧. Puoi sostituirmelo?", "." },
  ["d72ee89a04524f04"] = { "Domanda 1, catena 1?", "." },
  ["d73015736e3617ee"] = { "Dolce, dolce abbraccio... prendimi...", "." },
  ["d730edc5fddd457a"] = { "Oltre ai grunt là fuori, io e i miei fratelli abbiamo combattuto nella battaglia del Monte Hyjal. Chiunque voglia rubare alla banca dovrà prima vedersela con noi.", "." },
  ["d73c7548b124b0f2"] = { "Grazie, mi hai salvato la vita!\n\nMi occupo di cucina e di alchimia, e vengo da ⟦Stormwind=Roccavento⟧. Ero qui in cerca di erbe e ricette locali per mio zio Angus quando questi verrospini mi hanno teso un'imboscata. Se non fossi arrivat<o/a> tu, di sicuro la mia sorte sarebbe stata il loro pentolone dello stufato!", "." },
  ["d74597c540bdd054"] = { "Il Dun Baldar North Bunker protegge l'ingresso orientale di Dun Baldar.\n\nÈ controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["d7466c50a5286b2e"] = { "%s va in pezzi, ma continua a combattere", "." },
  ["d746c031bbdd7259"] = { "Una mosca senza ali si chiamerebbe «cammina»?", "." },
  ["d74a2d3c65e14b11"] = { "<La conestabile Aonda ha un'espressione intensa, chiaramente immersa nei suoi pensieri.>", "." },
  ["d74cc61c5aade82b"] = { "starnutisce violentemente!", "." },
  ["d753981775d38477"] = { "Mi spiace, <ragazzo/ragazza>, ma non hai le basi per imparare ciò che ho da insegnare. Ma non preoccuparti, va' a parlare con il mio allievo Rotgath, lui ti darà una mano.", "." },
  ["d75478c2b1ba6b56"] = { "Inviare assalti di terra richiede enormi quantità di rifornimenti!", "." },
  ["d75d730365052449"] = { "Uccidete le guardie, prendete vivo il direttore!", "." },
  ["d761fe09ee37b5c8"] = { "Grazie, <ragazzo/ragazza>. Grazie infinite.", "." },
  ["d7681ef3ef3178b0"] = { "Ah, {name}, che piacere sentire di nuovo il tuo odore.\n\n<Falthir sogghigna.>\n\nDovrai perdonare il mio senso dell'umorismo. A volte sa essere davvero fetido.\n\nSento che hai causato grande angoscia ai nostri nemici. Le forze di Hakkar gridano il tuo nome con rabbia. Questo è eccellente.\n\nTi sei guadagnat<o/a> un'altra trama sul tuo talismano. Consegnamelo.", "." },
  ["d7688b2be7a8638b"] = { "Larion, voglio aiutarti a combattere questi parassiti!", "." },
  ["d76b01a0803f4762"] = { "Basta con questi discorsi. Voglio parlare dei bei tempi. Garek l'avrebbe voluto per noi.", "." },
  ["d76b36a49002f59b"] = { "Ce l'hai fatta... hai ucciso il barone Fieramorte! L'⟦Argent Dawn=Alba d'Argento⟧ saprà delle tue valorose imprese!", "." },
  ["d76c05a3f73c8fdc"] = { "Preparatevi a un'eternità di angoscia e tortura: la vendetta sarà mia...", "." },
  ["d780bb3716062101"] = { "Quanto dolore... Il passsato non può essssere cancellato...", "." },
  ["d7817020f35f9991"] = { "Chi se la prende con Silas se la prende con me. Buona giornata.", "." },
  ["d781a330ecba2336"] = { "Sono tutt'orecchi.", "." },
  ["d7881cdde48aefee"] = { "Dov'è l'anziano Lamalesta?", "." },
  ["d78dc987aefed72a"] = { "Sì, <figlio/figlia> <mio/mia>? In cosa posso aiutarti?", "." },
  ["d797b8f55a7b0500"] = { "Libertà! Ora lavoriamo insieme per salvare mia sorella, Jarien!", "." },
  ["d79bd56b53aacca5"] = { "La guerra è una faccenda sanguinosa e sporca, piena di dolore, sofferenza e morte. Ma chi sopravvive torna con un nuovo rispetto per la vita. Per non parlare di una bella collezione di storie da raccontare al bancone, piene di audacia e coraggio. Allora dimmi, <ragazzo/ragazza>, sei qui per crearti qualche storia? O solo per ascoltare qualcuna delle mie?", "." },
  ["d79cd13e91baba32"] = { "Grazie, {name}! Finalmente libertà!!!", "." },
  ["d79e417dae9a4c65"] = { "È bello rivederti, Erland. Qual è il tuo rapporto?", "." },
  ["d79e8a9d5e4ba315"] = { "Buona fortuna con Arugal. Ora devo tornare in fretta da Hadrec.", "." },
  ["d7aa48f0c3c0ef20"] = { "Ah sì, è Seikwa che devi trovare. Credo di averla vista l'ultima volta davanti alla locanda.", "." },
  ["d7afb8aaed90a6f4"] = { "Non posso addestrarti.", "." },
  ["d7b1179974d2ed60"] = { "Quando il lavoro di un fabbro raggiunge il tuo livello di maestria, gli offro una scelta.\n\nNon sei obbligat<o/a> a scegliere, ma te lo consiglio: dopotutto, vuoi restare una recluta per sempre? Sono i forgiatori di armature e di armi più esperti a rifornire i nostri eserciti, a vincere le nostre guerre e a guadagnarsi la gloria!\n\nMa attenzione, {name}. Una volta fatta la scelta e completati i compiti richiesti, non si torna indietro. Si può percorrere un solo cammino.", "." },
  ["d7b7e3264977657b"] = { "È giunto il momento, Guse. Volerai di nuovo!", "." },
  ["d7c326d7a30364ff"] = { "Chiedo scusa, Lady Prestor.", "." },
  ["d7c35c0c51c63fad"] = { "Mmm? Oh sì, posso insegnarti qualcosa, se lo desideri. Ma sta' lontano da Sumi e Tumi, non sono per quelli come te. Saru permette solo a chi ha grande abilità di avvicinarsi alle sue figlie.", "." },
  ["d7cafbcaa59714f6"] = { "Ah, temo che tu e io non abbiamo affari da trattare, per ora.\n\nSe finirai per portare a termine qualche contratto con l'autorità commerciale, forse più avanti avremo qualcosa di cui discutere.", "." },
  ["d7cb0690f600b027"] = { "Per evocare un maldestriero, devi prima creare un Circle of Greater Summoning. Un portale per Xoroth può essere aperto solo dall'interno di un simile cerchio.\n\nIl Circle of Greater Summoning richiede tre potenti strumenti: una Bell of Dethmoora, una Wheel of the Black March e una Doomsday Candle.", "." },
  ["d7d8f09909bb21f8"] = { "Ah... {name}... figli<o/a> dei quattro venti... Cerchi comprensione. Cerchi risposte. Perché i venti ti hanno abbandonat<o/a>? Come puoi riaverli? Sono risposte che non posso darti, perché non conosco i motivi né i movimenti dei venti.\n\nPosso però insegnarti molto della terra. La sua forza, la sua determinazione. Anche qui, in alto in questo mare infinito di nuvole, sei ancora una creatura della terra. Se speri di trovare la forza per parlare di nuovo con gli spiriti dei quattro venti, questo è il sentiero che devi percorrere.", "." },
  ["d7dd5d370180e277"] = { "Prendi questo! Oh... devo aver premuto il pulsante sbagliato... Aspetta, prova questo!", "." },
  ["d7e047bfdb57fb83"] = { "Ho bisogno di aiuto.", "." },
  ["d7e37be0840e27c4"] = { "Come molti altri, ho raggiunto queste terre per aiutare i miei compagni druidi quando è iniziata la guerra.\n\nOra che le ⟦Gates of Ahn'Qiraj=Porte di Ahn'qiraj⟧ sono aperte, ho capito che c'è ancora molto lavoro da fare. Ho deciso di restare a ⟦Silithus=Silitus⟧ e di fare del mio meglio per aiutare la causa, {name}.", "." },
  ["d7e7acc99c047317"] = { "Il Capoguerra mi ha incaricato di studiare ogni genere di armi e armature. Mi ha mandato qui, nel cuore delle culture tauren e orchesca nelle ⟦Barrens=Savane⟧, per incontrare quanti più viaggiatori possibile e conoscere le culture delle ⟦Barrens=Savane⟧.\n\nRitiene che ci sia qualcosa da imparare persino dalle culture più patetiche... come quella dei verrospini o dei centauri.", "." },
  ["d7e966a79f1af63a"] = { "La porta è aperta, Kharan. Sei un uomo libero.", "." },
  ["d7ea414807c3fdee"] = { "Ahhh, allora quello che cerchi è il Visitor's Center di ⟦Stormwind=Roccavento⟧. È il primo edificio a sinistra quando attraversi i cancelli principali venendo dalla ⟦Valley of Heroes=Valle degli Eroi⟧.", "." },
  ["d7f14b8a44515360"] = { "Il suo grembiule! Dov'è?", "." },
  ["d7f1a938bfd8ef47"] = { "Continua...", "." },
  ["d7f2c23ace958a17"] = { "Forse riuscirai a battermi, ma i Defias SI RIPRENDERANNO ⟦Stormwind=Roccavento⟧!", "." },
  ["d7f4c3d6b85db408"] = { "Avventurieri da ogni dove vendono cose ad Antonio: venite a vedere con i vostri occhi quali piccoli tesori ha per voi questa settimana.", "." },
  ["d7f6a6c613aa3737"] = { "%s resta indifferente.", "." },
  ["d7fb90d41d6acdf9"] = { "%s è completamente avvolto dalle fiamme e nei suoi occhi compare uno sguardo folle!", "." },
  ["d7ff280c530ac060"] = { "Morte al direttore!", "." },
})
